/**
 * Name and level lookups for save data, backed by src/data/save-tables.json
 * (generated by `npm run generate-save-tables`).
 */
import tablesJson from "../../data/save-tables.json";

interface SaveTables {
  moves: string[];
  abilities: string[];
  items4: Record<string, string>;
  locations4: Record<string, string>;
  /** species id → growth rate id */
  growth: number[];
  /** growth rate id → total EXP needed for each level (index = level) */
  exp: Record<string, number[]>;
}

const tables = tablesJson as unknown as SaveTables;

export function moveName(id: number): string {
  return tables.moves[id] || `Move #${id}`;
}

export function abilityName(id: number): string {
  return tables.abilities[id] || `Ability #${id}`;
}

export function itemName(index: number): string {
  return tables.items4[index] ?? `Item #${index}`;
}

export function locationName(index: number): string {
  return tables.locations4[index] ?? `Location #${index}`;
}

// The ball byte uses item indices for the 16 standard balls; HeartGold/SoulSilver's
// Apricorn balls continue at 17 but sit at item index 492 onwards.
const FIRST_APRICORN_BALL = 17;
const FIRST_APRICORN_ITEM = 492;

export function ballName(ball: number): string {
  if (ball === 0) return "Poké Ball";
  return itemName(ball >= FIRST_APRICORN_BALL ? FIRST_APRICORN_ITEM + ball - FIRST_APRICORN_BALL : ball);
}

/** Boxed Pokémon don't store their level — it follows from EXP and the species' growth curve. */
export function levelFromExp(species: number, exp: number): number {
  const curve = tables.exp[tables.growth[species]];
  if (!curve) return 1;
  let level = 1;
  while (level < 100 && exp >= curve[level + 1]) level++;
  return level;
}

const ORIGIN_GAMES: Record<number, string> = {
  1: "Sapphire",
  2: "Ruby",
  3: "Emerald",
  4: "FireRed",
  5: "LeafGreen",
  7: "HeartGold",
  8: "SoulSilver",
  10: "Diamond",
  11: "Pearl",
  12: "Platinum",
  15: "Colosseum/XD",
};

export function originGameName(code: number): string {
  return ORIGIN_GAMES[code] ?? `Game #${code}`;
}
